package io.cascadeshield.sim;

import com.fasterxml.jackson.databind.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import static io.cascadeshield.sim.BenchmarkModels.*;

/** Frozen scenario declarations; all labels are generated by the authoritative simulator separately. */
public final class MlExperimentProtocol {
    private final JsonNode document;private final BenchmarkScenarioGenerator generator;private final ObjectMapper mapper;
    private record OwnedScenario(String split,ScenarioSpec scenario){}
    private Map<String,List<ScenarioSpec>> generated;private final Map<String,Integer> attempts=new HashMap<>();private final Map<String,String> coarseKeys=new HashMap<>(),abstractKeys=new HashMap<>();
    public MlExperimentProtocol(Path file,RoadGraph roads,ObjectMapper mapper)throws Exception{this.document=mapper.readTree(Files.readAllBytes(file));this.generator=new BenchmarkScenarioGenerator(roads,mapper);this.mapper=mapper;
        if(!"cascadeshield.milestone4-protocol/1.0".equals(document.path("schemaVersion").asText()))throw new IllegalArgumentException("Unsupported M4 protocol");
        Set<Long> all=new HashSet<>();for(JsonNode split:document.path("splits"))for(JsonNode seed:split)if(!seed.isIntegralNumber()||!all.add(seed.asLong()))throw new IllegalArgumentException("Seeds must be integral and disjoint across all splits");
        for(JsonNode seed:document.path("historicallyExposedSeeds"))if(all.contains(seed.asLong()))throw new IllegalArgumentException("An exposed historical seed cannot be reused");}
    public List<Double> clocks(){List<Double> out=new ArrayList<>();for(JsonNode v:document.path("snapshotClocksSec"))out.add(v.asDouble());return List.copyOf(out);}
    public List<ScenarioSpec> scenarios(String split){if(!document.path("splits").has(split))throw new IllegalArgumentException("Unknown split "+split);if(generated==null)build();return generated.get(split);}
    private void build(){Map<String,List<ScenarioSpec>> all=new LinkedHashMap<>();Map<String,String> owners=new HashMap<>();List<OwnedScenario> prior=new ArrayList<>();boolean guard=document.path("splitIsolation").path("enabled").asBoolean();
        for(String split:List.of("train","validation","calibration","final")){List<ScenarioSpec> result=new ArrayList<>();
        for(JsonNode seedNode:document.path("splits").path(split)){long seed=seedNode.asLong();int familyIndex=0;for(JsonNode family:document.path("families")){
            int index=familyIndex++;if(family.path("finalOnly").asBoolean()&&!"final".equals(split))continue;
            int maximum=document.path("splitIsolation").path("maxResampleAttempts").asInt(256);
            ScenarioSpec chosen=null;for(int attempt=0;attempt<maximum;attempt++){ScenarioSpec candidate=generate(family,index,seed,attempt,split);String coarse=coarseFingerprint(candidate),abstractKey=abstractFingerprint(candidate);String owner=owners.get("primary:"+coarse),abstractOwner=owners.get("abstract:"+abstractKey);
                boolean continuousConflict=guard&&prior.stream().anyMatch(v->!v.split().equals(split)&&continuouslyNear(candidate,v.scenario()));
                if(!guard||((owner==null||owner.equals(split))&&(abstractOwner==null||abstractOwner.equals(split))&&!continuousConflict)){chosen=candidate;owners.putIfAbsent("primary:"+coarse,split);owners.putIfAbsent("abstract:"+abstractKey,split);attempts.put(chosen.id(),attempt);coarseKeys.put(chosen.id(),coarse);abstractKeys.put(chosen.id(),abstractKey);break;}}
            if(chosen==null)throw new IllegalArgumentException("Could not isolate physical scenario group after "+maximum+" input-only resamples");result.add(chosen);prior.add(new OwnedScenario(split,chosen));
        }}all.put(split,List.copyOf(result));}generated=Collections.unmodifiableMap(all);}
    private ScenarioSpec generate(JsonNode family,int index,long seed,int attempt,String split){
            @SuppressWarnings("unchecked") Map<String,Object> p=mapper.convertValue(family.path("parameters"),LinkedHashMap.class);
            JsonNode fleet=document.path("splitIsolation").path("fleetSizeGroups");if(fleet.isObject()){
                String baseCount=String.valueOf(((Number)p.get("truckCount")).intValue());JsonNode mapped=fleet.path(split).path(baseCount);
                if(!mapped.isIntegralNumber())throw new IllegalArgumentException("Missing predeclared actual fleet-size mapping for "+split+" base "+baseCount);
                p.put("truckCount",mapped.asInt());}
            Random random=new Random(seed*104729+index*1009+17+attempt*1000003L);scale(p,"serviceSec",.85+.3*random.nextDouble());scale(p,"departureGapSec",.85+.3*random.nextDouble());
            scale(p,"incidentDurationSec",.75+.5*random.nextDouble());p.put("incidentStartSec",tick(10+50*random.nextDouble()));
            p.put("severity",tick(Math.max(.05,Math.min(1,((Number)p.getOrDefault("severity",1d)).doubleValue()-.1+.2*random.nextDouble()))));
            p.put("driverRestoreSec",tick(Math.max(0,((Number)p.getOrDefault("driverRestoreSec",300d)).doubleValue()-60+120*random.nextDouble())));
            for(String key:List.of("decisionIntervalSec","rolloutHorizonSec","maxDecisions"))p.put(key,mapper.convertValue(document.path("policyBudget").path(key),Number.class));
            ScenarioSpec base=generator.generate(family.path("baseProfile").asText(),seed,p);assertActualFleetCount(base,((Number)p.get("truckCount")).intValue());String id=family.path("id").asText();
            return new ScenarioSpec(id+"-s"+seed+"-"+base.inputFingerprint().substring(0,12),id+" / seed "+seed,seed,id,base.configuration(),base.exogenousSchedule(),base.horizonSec(),base.inputFingerprint(),base.parameters(),base.provenance());}
    /** Predeclared coarse equivalence ignores identifiers, speed/load jitter and exact decimal timing. */
    @SuppressWarnings("unchecked") public String coarseFingerprint(ScenarioSpec s){Map<String,Object> q=s.configuration(),p=s.parameters();Map<String,Object> ops=mapper.convertValue(q.get("operations"),Map.class);
        List<Object> od=new ArrayList<>();for(Object raw:(List<?>)q.get("trucks")){Map<String,Object> t=mapper.convertValue(raw,Map.class);od.add(List.of(t.get("start"),t.get("destination")));}
        List<Object> assignments=new ArrayList<>();for(Object raw:(List<?>)ops.get("assignments")){Map<String,Object>a=mapper.convertValue(raw,Map.class);assignments.add(List.of(a.get("truckId"),a.get("driverId"),a.get("dockId"),a.get("deliveryIds")));}
        List<Object> availability=new ArrayList<>();for(Object raw:(List<?>)ops.get("drivers"))availability.add(((Map<?,?>)raw).get("available"));
        List<Object> events=new ArrayList<>();for(var c:s.exogenousSchedule()){Map<String,Object> e=new LinkedHashMap<>();e.put("kind",c.kind());e.put("type",c.payload().get("type"));e.put("physicalId",c.payload().get("physicalId"));e.put("clockBin",bin(c.clockSec(),60));e.put("durationBin",bin(c.payload().getOrDefault("durationSec",0d),60));e.put("severityBin",bin(c.payload().getOrDefault("severity",0d),.2));events.add(e);}
        return generator.hash(Map.of("od",od,"assignments",assignments,"driverAvailability",availability,"warehouseCount",p.get("warehouseCount"),"dockCount",p.get("docksPerWarehouse"),"serviceBin",bin(p.get("serviceSec"),60),"departureGapBin",bin(p.get("departureGapSec"),30),"deadlineSlackBin",bin(p.get("deadlineSlackSec"),60),"events",events));}
    @SuppressWarnings("unchecked") private void assertActualFleetCount(ScenarioSpec spec,int expected){Map<String,Object> ops=mapper.convertValue(spec.configuration().get("operations"),Map.class);
        for(String key:List.of("drivers","deliveries","assignments"))if(((List<?>)ops.get(key)).size()!=expected)throw new IllegalStateException("Actual "+key+" count differs from declared fleet size");
        if(((List<?>)spec.configuration().get("trucks")).size()!=expected)throw new IllegalStateException("Actual truck count differs from declared fleet size");}
    /** Conservative second grouping ignores edge/assignment jitter and uses coarser exposure categories. */
    @SuppressWarnings("unchecked") public String abstractFingerprint(ScenarioSpec s){Map<String,Object> q=s.configuration(),p=s.parameters();Map<String,Object> ops=mapper.convertValue(q.get("operations"),Map.class);Map<String,Object> key=new TreeMap<>();List<String> od=new ArrayList<>();
        for(Object raw:(List<?>)q.get("trucks")){Map<String,Object> t=mapper.convertValue(raw,Map.class);od.add(generator.hash(List.of(t.get("start"),t.get("destination"))));}Collections.sort(od);key.put("odMultiset",od);
        key.put("truckCount",p.get("truckCount"));key.put("warehouseCount",p.get("warehouseCount"));key.put("dockCount",p.get("docksPerWarehouse"));long unavailable=((List<?>)ops.get("drivers")).stream().filter(d->!Boolean.TRUE.equals(((Map<?,?>)d).get("available"))).count();key.put("unavailableCount",unavailable);
        for(var b:Map.of("serviceSec",60d,"departureGapSec",30d,"incidentDurationSec",120d,"deadlineSlackSec",60d,"severity",.25d,"incidentStartSec",60d,"contention",.25d).entrySet())key.put(b.getKey(),(long)Math.floor(((Number)p.get(b.getKey())).doubleValue()/b.getValue()));
        key.put("driverRestoreSec",unavailable>0?(long)Math.floor(((Number)p.get("driverRestoreSec")).doubleValue()/120):-1L);
        Map<String,Integer> types=new TreeMap<>();for(var c:s.exogenousSchedule())types.merge(c.kind()+":"+c.payload().getOrDefault("type",""),1,Integer::sum);key.put("eventTypeCounts",types);key.put("simultaneousIncidents",p.get("simultaneousIncidents"));return generator.hash(key);}
    /** Unquantized guard prevents two neighboring bins disguising near-identical cases. */
    @SuppressWarnings("unchecked") public boolean continuouslyNear(ScenarioSpec a,ScenarioSpec b){if(!structuralFingerprint(a).equals(structuralFingerprint(b)))return false;
        Map<String,Double> widths=new LinkedHashMap<>(Map.of("serviceSec",60d,"departureGapSec",30d,"deadlineSlackSec",60d,"contention",.25d));
        boolean incident=a.exogenousSchedule().stream().anyMatch(c->c.kind().equals("INCIDENT_ADD"));if(incident){widths.put("incidentDurationSec",120d);widths.put("severity",.25d);widths.put("incidentStartSec",60d);}
        Map<String,Object> ops=mapper.convertValue(a.configuration().get("operations"),Map.class);boolean unavailable=((List<?>)ops.get("drivers")).stream().anyMatch(d->!Boolean.TRUE.equals(((Map<?,?>)d).get("available")));if(unavailable)widths.put("driverRestoreSec",120d);
        for(var entry:widths.entrySet())if(Math.abs(((Number)a.parameters().get(entry.getKey())).doubleValue()-((Number)b.parameters().get(entry.getKey())).doubleValue())>=entry.getValue()-1e-8)return false;return true;}
    @SuppressWarnings("unchecked") public String structuralFingerprint(ScenarioSpec s){Map<String,Object> ops=mapper.convertValue(s.configuration().get("operations"),Map.class);List<String> od=new ArrayList<>();
        for(Object raw:(List<?>)s.configuration().get("trucks")){Map<String,Object> t=mapper.convertValue(raw,Map.class);od.add(generator.hash(List.of(t.get("start"),t.get("destination"))));}Collections.sort(od);
        long unavailable=((List<?>)ops.get("drivers")).stream().filter(d->!Boolean.TRUE.equals(((Map<?,?>)d).get("available"))).count();Map<String,Integer> types=new TreeMap<>();for(var c:s.exogenousSchedule())types.merge(c.kind()+":"+c.payload().getOrDefault("type",""),1,Integer::sum);
        return generator.hash(Map.of("odMultiset",od,"truckCount",((List<?>)s.configuration().get("trucks")).size(),"warehouseCount",((List<?>)ops.get("warehouses")).size(),"dockCount",((List<?>)ops.get("docks")).size(),"unavailableCount",unavailable,"eventTypeCounts",types,"simultaneousIncidents",s.parameters().get("simultaneousIncidents")));}
    private static long bin(Object n,double width){return Math.round(((Number)n).doubleValue()/width);}
    public Map<String,Object> manifest(String graphSha,String protocolSha){List<Map<String,Object>> cases=new ArrayList<>();Map<String,String> scheduledGroups=new HashMap<>(),configurationGroups=new HashMap<>();
        for(String split:List.of("train","validation","calibration","final"))for(ScenarioSpec s:scenarios(split)){
            String schedule=generator.hash(s.exogenousSchedule());Map<String,Object> configuration=new LinkedHashMap<>(s.configuration());configuration.remove("randomSeed");configuration.remove("seed");configuration.remove("scenarioName");
            String config=generator.hash(configuration);rejectCrossSplit(configurationGroups,config,split,"configuration");if(!s.exogenousSchedule().isEmpty())rejectCrossSplit(scheduledGroups,schedule,split,"incident/restoration schedule");
            Map<String,Object> row=new LinkedHashMap<>();row.put("split",split);row.put("scenario",s);row.put("scheduleFingerprint",schedule);row.put("configurationFingerprint",config);row.put("coarseGroupFingerprint",coarseKeys.get(s.id()));row.put("abstractGroupFingerprint",abstractKeys.get(s.id()));row.put("structuralGroupFingerprint",structuralFingerprint(s));row.put("inputOnlyResampleAttempt",attempts.get(s.id()));cases.add(row);
        }
        return Map.of("schemaVersion","cascadeshield.ml-generation-manifest/1.0","protocolSha256",protocolSha,"graphSha256",graphSha,"cases",cases,"provenance",PROVENANCE,
            "splitRule","Entire seeded operation and all related frames stay together; exposed M3 seeds excluded; exact cross-split configuration/nonempty schedule duplicates rejected; v2 holds out actual fleet sizes and independently rejects coarse, abstract and continuous-near cross-split groups. Evaluation is fleet-size transfer on a shared bounded network, not an IID or geographic split",
            "finalOutcomeRule","Final inputs declared before selection; labels generated only after a frozen artifact manifest is supplied");}
    private static void rejectCrossSplit(Map<String,String> groups,String hash,String split,String name){String previous=groups.putIfAbsent(hash,split);if(previous!=null&&!previous.equals(split))throw new IllegalArgumentException("Cross-split duplicate "+name);}
    private static void scale(Map<String,Object> p,String key,double scale){p.put(key,tick(((Number)p.get(key)).doubleValue()*scale));}
    private static double tick(double n){return Math.round(n*10)/10d;}
    public static String sha(byte[] bytes){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}catch(Exception e){throw new IllegalStateException(e);}}
}
